CREATE TABLE IF NOT EXISTS `spider_task` (`id` int AUTO_INCREMENT PRIMARY KEY,`task_uuid` varchar(64) NOT NULL UNIQUE,`task_name` varchar(255) NOT NULL,`task_type` varchar(80) NOT NULL,`seed_uuid` varchar(64),`carrier_type` varchar(40) NOT NULL DEFAULT 'rss_atom',`priority_level` varchar(24) NOT NULL DEFAULT 'normal',`region` varchar(80),`proxy_strategy` json,`fingerprint_profile` json,`rate_limit_policy` json,`ai_enabled` boolean NOT NULL DEFAULT true,`retry_policy` json,`backfill_enabled` boolean NOT NULL DEFAULT false,`checkpoint_json` json,`schedule_level` varchar(24) NOT NULL DEFAULT 'hourly',`status` varchar(24) NOT NULL DEFAULT 'paused',`last_run_at` timestamp NULL,`next_run_at` timestamp NULL,`created_by_user_id` int NOT NULL,`created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX `spider_task_status_priority_idx` (`status`,`priority_level`,`updated_at`));
CREATE TABLE IF NOT EXISTS `spider_seed_pool` (`id` int AUTO_INCREMENT PRIMARY KEY,`seed_uuid` varchar(64) NOT NULL UNIQUE,`seed_url` text NOT NULL,`domain` varchar(255) NOT NULL,`source_name` varchar(255) NOT NULL,`source_category` varchar(80) NOT NULL,`language` varchar(24),`region` varchar(80),`robots_policy` varchar(40) NOT NULL DEFAULT 'unknown',`crawl_depth` int NOT NULL DEFAULT 1,`priority` int NOT NULL DEFAULT 100,`discovered_by_ai` boolean NOT NULL DEFAULT false,`discovery_source_uuid` varchar(64),`health_status` varchar(24) NOT NULL DEFAULT 'unchecked',`last_checked_at` timestamp NULL,`last_http_status` int,`is_active` boolean NOT NULL DEFAULT true,`created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX `spider_seed_domain_status_idx` (`domain`,`health_status`,`updated_at`));
CREATE TABLE IF NOT EXISTS `spider_raw_data` (`id` int AUTO_INCREMENT PRIMARY KEY,`raw_uuid` varchar(64) NOT NULL UNIQUE,`task_uuid` varchar(64),`seed_uuid` varchar(64),`source_url` text NOT NULL,`carrier_type` varchar(40) NOT NULL,`content_type` varchar(120),`raw_binary` longtext,`raw_content` longtext,`response_headers` json,`source_language` varchar(24),`content_hash` varchar(64) NOT NULL,`http_status` int,`crawl_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`parse_status` varchar(24) NOT NULL DEFAULT 'pending',`archive_snapshot` longtext,UNIQUE KEY `spider_raw_content_hash_uq` (`content_hash`),INDEX `spider_raw_task_time_idx` (`task_uuid`,`crawl_time`));
CREATE TABLE IF NOT EXISTS `spider_ai_processed` (`id` int AUTO_INCREMENT PRIMARY KEY,`process_uuid` varchar(64) NOT NULL UNIQUE,`raw_uuid` varchar(64) NOT NULL,`parser_type` varchar(40) NOT NULL,`ai_model` varchar(120),`extracted_entities` json,`normalized_content` longtext,`rewritten_content` longtext,`formula_struct` json,`quality_level` varchar(16) NOT NULL DEFAULT 'L4',`quality_checks` json,`process_status` varchar(24) NOT NULL DEFAULT 'pending',`error_detail` longtext,`created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX `spider_ai_raw_status_idx` (`raw_uuid`,`process_status`,`updated_at`));
CREATE TABLE IF NOT EXISTS `finance_world_dataset` (`id` int AUTO_INCREMENT PRIMARY KEY,`uuid` varchar(64) NOT NULL UNIQUE,`data_top_type` varchar(80) NOT NULL,`data_sub_type` varchar(120) NOT NULL,`source_url` text NOT NULL,`source_name` varchar(255) NOT NULL,`source_language` varchar(24),`raw_binary` longtext,`raw_content` longtext,`ai_process_content` longtext,`region` varchar(80),`country` varchar(120),`exchange` varchar(120),`isin_code` varchar(32),`sedol_code` varchar(32),`asset_code` varchar(80),`asset_type` varchar(80),`list_status` varchar(40),`list_date` date,`delist_date` date,`time_series_json` json,`finance_array_json` json,`money_flow_json` json,`entity_relation_ids` json,`tag_list` json,`candidate_push_module_ids` json,`is_push` boolean NOT NULL DEFAULT false,`push_record_id` varchar(64),`data_quality_level` varchar(16) NOT NULL DEFAULT 'L4',`data_blood_id` varchar(64),`crawl_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,`archive_snapshot` longtext,INDEX `finance_world_type_region_idx` (`data_top_type`,`asset_type`,`region`),INDEX `finance_world_asset_idx` (`asset_code`,`exchange`));
CREATE TABLE IF NOT EXISTS `finance_tool_union_set` (`id` int AUTO_INCREMENT PRIMARY KEY,`tool_uuid` varchar(64) NOT NULL UNIQUE,`tool_name` varchar(255) NOT NULL,`tool_top_category` varchar(100) NOT NULL,`tool_sub_category` varchar(120) NOT NULL,`tool_version` varchar(80) NOT NULL,`formula_raw` longtext,`formula_parsed_struct` json,`input_params` json,`output_params` json,`depend_tool_uuids` json,`apply_market` json,`apply_asset_type` json,`risk_level` varchar(24),`scene_desc` longtext,`limitation_desc` longtext,`sample_case` json,`backtest_sample` json,`source_url` text NOT NULL,`source_doc_raw` longtext,`ai_standard_doc` longtext,`tag_list` json,`candidate_push_module_ids` json,`data_quality_level` varchar(16) NOT NULL DEFAULT 'L4',`data_blood_id` varchar(64),`crawl_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX `finance_tool_category_risk_idx` (`tool_top_category`,`tool_sub_category`,`risk_level`));
CREATE TABLE IF NOT EXISTS `spider_push_relation` (`id` int AUTO_INCREMENT PRIMARY KEY,`uuid` varchar(64) NOT NULL UNIQUE,`data_uuid` varchar(64) NOT NULL,`data_collection` varchar(64) NOT NULL,`target_front_module_ids` json NOT NULL,`operator` varchar(160) NOT NULL,`operator_user_id` int NOT NULL,`operate_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`push_status` varchar(24) NOT NULL DEFAULT 'pending',`push_detail` longtext,INDEX `spider_push_data_time_idx` (`data_uuid`,`operate_time`));
CREATE TABLE IF NOT EXISTS `spider_missing_scan_log` (`id` int AUTO_INCREMENT PRIMARY KEY,`scan_uuid` varchar(64) NOT NULL UNIQUE,`scan_type` varchar(40) NOT NULL,`source_scope` longtext,`target_scope` longtext,`missing_type` varchar(80) NOT NULL,`missing_keys` json,`missing_count` int NOT NULL DEFAULT 0,`threshold_json` json,`generated_task_uuids` json,`scan_status` varchar(24) NOT NULL DEFAULT 'completed',`detail` longtext,`started_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`completed_at` timestamp NULL,INDEX `spider_missing_type_time_idx` (`missing_type`,`started_at`));
CREATE TABLE IF NOT EXISTS `spider_fail_log` (`id` int AUTO_INCREMENT PRIMARY KEY,`fail_uuid` varchar(64) NOT NULL UNIQUE,`task_uuid` varchar(64),`raw_uuid` varchar(64),`stage` varchar(40) NOT NULL,`fail_type` varchar(80) NOT NULL,`source_url` text,`error_detail` longtext,`retry_count` int NOT NULL DEFAULT 0,`retry_strategy` varchar(80),`status` varchar(24) NOT NULL DEFAULT 'open',`last_retry_at` timestamp NULL,`created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX `spider_fail_stage_status_idx` (`stage`,`status`,`updated_at`));
CREATE TABLE IF NOT EXISTS `spider_entity_link` (`id` int AUTO_INCREMENT PRIMARY KEY,`link_uuid` varchar(64) NOT NULL UNIQUE,`source_entity_uuid` varchar(64) NOT NULL,`source_entity_type` varchar(60) NOT NULL,`target_entity_uuid` varchar(64) NOT NULL,`target_entity_type` varchar(60) NOT NULL,`relation_type` varchar(80) NOT NULL,`confidence` decimal(6,4) NOT NULL DEFAULT 0,`evidence_raw_uuids` json,`created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX `spider_entity_source_target_idx` (`source_entity_uuid`,`target_entity_uuid`));
CREATE TABLE IF NOT EXISTS `spider_data_blood` (`id` int AUTO_INCREMENT PRIMARY KEY,`data_blood_id` varchar(64) NOT NULL UNIQUE,`structured_data_uuid` varchar(64) NOT NULL,`collection_name` varchar(80) NOT NULL,`raw_uuids` json NOT NULL,`process_uuids` json NOT NULL,`source_urls` json NOT NULL,`transformation_steps` json NOT NULL,`created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX `spider_blood_structured_idx` (`structured_data_uuid`,`collection_name`));
CREATE TABLE IF NOT EXISTS `spider_content_snapshot` (`id` int AUTO_INCREMENT PRIMARY KEY,`snapshot_uuid` varchar(64) NOT NULL UNIQUE,`entity_uuid` varchar(64) NOT NULL,`entity_type` varchar(60) NOT NULL,`version` int NOT NULL,`source_url` text,`content_hash` varchar(64) NOT NULL,`raw_uuid` varchar(64),`snapshot_content` longtext,`change_summary` longtext,`created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY `spider_snapshot_entity_version_uq` (`entity_uuid`,`version`),INDEX `spider_snapshot_entity_time_idx` (`entity_uuid`,`created_at`));
